INSERT INTO `banners` VALUES (1,'Fresh Vegetables Delivered Every Day','Harvested at dawn, at your door by lunch. 100% quality-checked produce from partner farms.','https://images.unsplash.com/photo-1542838132-92c53300491e?q=80&w=2000&auto=format&fit=crop','Shop Now','/products?category=vegetables',0,1,'2026-07-15 14:33:53'),(2,'Farm Fresh Fruits','Tree-ripened, hand-picked, and bursting with flavour. Wholesale and retail.','https://images.unsplash.com/photo-1619566636858-adf3ef46400b?q=80&w=2000&auto=format&fit=crop','Shop Now','/products?category=fruits',1,1,'2026-07-15 14:33:53'),(3,'Premium Quality Meat & Seafood','Cold-chain delivered cuts and ocean-fresh catch, trusted by top restaurants.','https://images.unsplash.com/photo-1607623814075-e51df1bdc82f?q=80&w=2000&auto=format&fit=crop','Shop Now','/products?category=fresh-meat',2,1,'2026-07-15 14:33:53');
