INSERT INTO `categories` VALUES (1,'Vegetables','vegetables','Farm-fresh vegetables harvested daily and quality checked.','https://images.unsplash.com/photo-1540420773420-3366772f4999?q=80&w=1200&auto=format&fit=crop',NULL,0,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(2,'Leafy Vegetables','leafy-vegetables','Crisp greens picked at dawn.','https://images.unsplash.com/photo-1576045057995-568f588f82fb?q=80&w=1200&auto=format&fit=crop',1,1,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(3,'Root Vegetables','root-vegetables','Earthy roots full of flavour.','https://images.unsplash.com/photo-1598170845058-32b9d6a5da37?q=80&w=1200&auto=format&fit=crop',1,2,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(4,'Fruits','fruits','Sweet, juicy fruits from trusted orchards.','https://images.unsplash.com/photo-1619566636858-adf3ef46400b?q=80&w=1200&auto=format&fit=crop',NULL,3,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(5,'Exotic Fruits','exotic-fruits','Rare and tropical picks.','https://images.unsplash.com/photo-1550258987-190a2d41a8ba?q=80&w=1200&auto=format&fit=crop',4,4,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(6,'Seasonal Fruits','seasonal-fruits','The best of every season.','https://images.unsplash.com/photo-1464965911861-746a04b4bca6?q=80&w=1200&auto=format&fit=crop',4,5,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(7,'Fresh Meat','fresh-meat','Premium cuts, hygienically processed and chilled.','https://images.unsplash.com/photo-1607623814075-e51df1bdc82f?q=80&w=1200&auto=format&fit=crop',NULL,6,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(8,'Chicken','chicken','Farm-raised, antibiotic-free chicken.','https://images.unsplash.com/photo-1587593810167-a84920ea0781?q=80&w=1200&auto=format&fit=crop',7,7,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(9,'Mutton','mutton','Tender premium mutton cuts.','https://images.unsplash.com/photo-1603048297172-c92544798d5a?q=80&w=1200&auto=format&fit=crop',7,8,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(10,'Beef','beef','Grass-fed premium beef.','https://images.unsplash.com/photo-1607623814075-e51df1bdc82f?q=80&w=1200&auto=format&fit=crop',7,9,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(11,'Seafood','seafood','Ocean-fresh catch, delivered on ice.','https://images.unsplash.com/photo-1559339352-11d035aa65de?q=80&w=1200&auto=format&fit=crop',NULL,10,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(12,'Fish','fish','Daily catch from coastal waters.','https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?q=80&w=1200&auto=format&fit=crop',11,11,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(13,'Prawns','prawns','Sweet, succulent prawns.','https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?q=80&w=1200&auto=format&fit=crop',11,12,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(14,'Crab','crab','Live and fresh crabs.','https://images.unsplash.com/photo-1559737558-2f5a35f4523b?q=80&w=1200&auto=format&fit=crop',11,13,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(15,'Eggs','eggs','Free-range and farm eggs collected daily.','https://images.unsplash.com/photo-1506976785307-8732e854ad03?q=80&w=1200&auto=format&fit=crop',NULL,14,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(16,'Dairy','dairy','Fresh milk, cheese, butter and yogurt.','https://images.unsplash.com/photo-1550583724-b2692b85b150?q=80&w=1200&auto=format&fit=crop',NULL,15,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(17,'Frozen Foods','frozen-foods','Flash-frozen goodness, ready when you are.','https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?q=80&w=1200&auto=format&fit=crop',NULL,16,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(18,'Organic Products','organic-products','Certified organic produce and pantry staples.','https://images.unsplash.com/photo-1542838132-92c53300491e?q=80&w=1200&auto=format&fit=crop',NULL,17,1,1,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(19,'Spices','spices','Aromatic whole and ground spices.','https://images.unsplash.com/photo-1596040033229-a9821ebd058d?q=80&w=1200&auto=format&fit=crop',NULL,18,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53'),(20,'Dry Fruits','dry-fruits','Premium nuts and dried fruits.','https://images.unsplash.com/photo-1508061253366-f7da158b6d46?q=80&w=1200&auto=format&fit=crop',NULL,19,1,0,'2026-07-15 14:33:53','2026-07-15 14:33:53');
