INSERT INTO `testimonials` VALUES (1,'Sarah Mitchell','Home Chef','https://images.unsplash.com/photo-1494790108377-be9c29b29330?q=80&w=200&auto=format&fit=crop',5,'The strawberries actually smell like strawberries. I\'ve stopped going to the supermarket entirely — the enquiry process is quick and their team calls back within the hour.',1,0,'2026-07-15 14:33:53'),(2,'Chef Marco Rossi','Head Chef, Trattoria Verde','https://images.unsplash.com/photo-1583394838336-acd977736f90?q=80&w=200&auto=format&fit=crop',5,'We source our entire produce line through FreshMart\'s wholesale program. Consistent grading, honest pricing, and the cold chain is never broken. Rare in this business.',1,1,'2026-07-15 14:33:53'),(3,'Priya Nair','Restaurant Owner','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?q=80&w=200&auto=format&fit=crop',5,'Their mutton and seafood quality is unmatched. Same-day delivery means my menu never has to compromise. Highly recommended for any food business.',1,2,'2026-07-15 14:33:53'),(4,'David Okafor','Family Customer','https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=200&auto=format&fit=crop',4,'Ordering for a family of six every week. The organic vegetable box is superb value and the kids can actually taste the difference in the fruit.',1,3,'2026-07-15 14:33:53');
